PRAGMA foreign_keys = ON;

-- Published diagnostic in the shared library, not assigned to any student.
-- Manual assignment: /student-portal/admin/self-checks
INSERT OR IGNORE INTO self_check_tests
  (id, slug, version, title, description, subject, topic, level, estimated_minutes, status)
VALUES ('posloupnosti-ss-diagnostika-v1', 'posloupnosti-ss-diagnostika', '1', 'Posloupnosti — diagnostický self-check (SŠ, 32 úloh)', '[[calculator:Bez kalkulačky]]32 úloh / 64 bodů / přibližně 50 minut. Obecný člen, graf, indexové dosazování, znaménka, rovnice a nerovnice, hledání předpisu, rekurence a monotónnost. Obtížnost postupně roste. Jedna správná možnost u každé otázky. Po vyhodnocení se zobrazí vysvětlení.', 'Matematika', 'Posloupnosti', 'SŠ', '50', 'published');

INSERT OR IGNORE INTO self_check_questions
  (id, test_id, position, prompt, options_json, correct_answer, explanation, points)
VALUES
  ('posloupnosti-ss-diagnostika-v1-q01', 'posloupnosti-ss-diagnostika-v1', '1', '{"instruction":"Urči první člen.","math":"a_n=n+(-1)^n","category":"Základní členy a pravidla","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:0]]"},{"id":"b","label":"[[math:1]]"},{"id":"c","label":"[[math:2]]"},{"id":"d","label":"[[math:-1]]"}]', 'a', 'a1=1+(−1)=0.', '1'),
  ('posloupnosti-ss-diagnostika-v1-q02', 'posloupnosti-ss-diagnostika-v1', '2', '{"instruction":"Urči čtvrtý člen.","math":"a_n=2-n","category":"Základní členy a pravidla","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:−4]]"},{"id":"b","label":"[[math:−2]]"},{"id":"c","label":"[[math:2]]"},{"id":"d","label":"[[math:6]]"}]', 'b', 'a4=2−4=−2.', '1'),
  ('posloupnosti-ss-diagnostika-v1-q03', 'posloupnosti-ss-diagnostika-v1', '3', '{"instruction":"Urči dvacátý člen.","math":"a_n=\\frac{n-1}{n+1}","category":"Základní členy a pravidla","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:19/21]]"},{"id":"b","label":"[[math:20/21]]"},{"id":"c","label":"[[math:21/19]]"},{"id":"d","label":"[[math:19/20]]"}]', 'a', 'a20=(20−1)/(20+1)=19/21.', '1'),
  ('posloupnosti-ss-diagnostika-v1-q04', 'posloupnosti-ss-diagnostika-v1', '4', '{"instruction":"Vyber předpis pro členy 2, 4, 6, 8, …","math":"","category":"Základní členy a pravidla","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:n]]"},{"id":"b","label":"[[math:2n]]"},{"id":"c","label":"[[math:n+2]]"},{"id":"d","label":"[[math:2^n]]"}]', 'b', 'Násobky dvojky mají předpis a_n=2n.', '1'),
  ('posloupnosti-ss-diagnostika-v1-q05', 'posloupnosti-ss-diagnostika-v1', '5', '{"instruction":"Vyber předpis pro členy 1, 3, 5, 7, …","math":"","category":"Základní členy a pravidla","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:2n+1]]"},{"id":"b","label":"[[math:n^2]]"},{"id":"c","label":"[[math:2n-1]]"},{"id":"d","label":"[[math:n+1]]"}]', 'c', 'První liché číslo musí vyjít při n=1: 2n−1.', '1'),
  ('posloupnosti-ss-diagnostika-v1-q06', 'posloupnosti-ss-diagnostika-v1', '6', '{"instruction":"Vyber předpis pro členy 1, 8, 27, 64, …","math":"","category":"Základní členy a pravidla","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:n^2]]"},{"id":"b","label":"[[math:2^n]]"},{"id":"c","label":"[[math:n^3]]"},{"id":"d","label":"[[math:3n]]"}]', 'c', 'Jsou to třetí mocniny 1³, 2³, 3³, 4³.', '1'),
  ('posloupnosti-ss-diagnostika-v1-q07', 'posloupnosti-ss-diagnostika-v1', '7', '{"instruction":"Spočítej a4.","math":"a_1=1,\\quad a_{n+1}=5-a_n","category":"Základní členy a pravidla","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:1]]"},{"id":"b","label":"[[math:4]]"},{"id":"c","label":"[[math:5]]"},{"id":"d","label":"[[math:−4]]"}]', 'b', 'a1=1, a2=4, a3=1, a4=4.', '1'),
  ('posloupnosti-ss-diagnostika-v1-q08', 'posloupnosti-ss-diagnostika-v1', '8', '{"instruction":"Spočítej a5.","math":"a_1=8,\\quad a_{n+1}=\\frac12a_n","category":"Základní členy a pravidla","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:1]]"},{"id":"b","label":"[[math:1/2]]"},{"id":"c","label":"[[math:2]]"},{"id":"d","label":"[[math:1/4]]"}]', 'b', 'Opakovaně půlíme: 8, 4, 2, 1, 1/2.', '1'),
  ('posloupnosti-ss-diagnostika-v1-q09', 'posloupnosti-ss-diagnostika-v1', '9', '{"instruction":"Spočítej a3.","math":"a_n=\\frac{5-n^2}{n}","category":"Dosazování indexů a znaménka","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:−4/3]]"},{"id":"b","label":"[[math:4/3]]"},{"id":"c","label":"[[math:−2/3]]"},{"id":"d","label":"[[math:−4]]"}]', 'a', 'a3=(5−9)/3=−4/3.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q10', 'posloupnosti-ss-diagnostika-v1', '10', '{"instruction":"Vyjádři člen a_(n+1).","math":"a_n=2-3n","category":"Dosazování indexů a znaménka","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:2-3n]]"},{"id":"b","label":"[[math:-1-3n]]"},{"id":"c","label":"[[math:5-3n]]"},{"id":"d","label":"[[math:-1+3n]]"}]', 'b', 'a_(n+1)=2−3(n+1)=−1−3n.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q11', 'posloupnosti-ss-diagnostika-v1', '11', '{"instruction":"Vyjádři člen a_(2n).","math":"a_n=(\\frac12)^{n-1}","category":"Dosazování indexů a znaménka","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:2^{1-2n}]]"},{"id":"b","label":"[[math:2^{2n-1}]]"},{"id":"c","label":"[[math:2^{-n}]]"},{"id":"d","label":"[[math:2^{1-n}]]"}]', 'a', 'a_(2n)=(1/2)^(2n−1)=2^(1−2n).', '2'),
  ('posloupnosti-ss-diagnostika-v1-q12', 'posloupnosti-ss-diagnostika-v1', '12', '{"instruction":"Vyjádři člen a_(k+2).","math":"a_n=n+(-1)^n","category":"Dosazování indexů a znaménka","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:k+2-(-1)^k]]"},{"id":"b","label":"[[math:k+(-1)^k]]"},{"id":"c","label":"[[math:k+2+(-1)^k]]"},{"id":"d","label":"[[math:k+2+(-1)^{k+1}]]"}]', 'c', 'a_(k+2)=k+2+(−1)^(k+2)=k+2+(−1)^k.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q13', 'posloupnosti-ss-diagnostika-v1', '13', '{"instruction":"Vyber první čtyři členy.","math":"a_n=0{,}6(1+(-1)^n)","category":"Dosazování indexů a znaménka","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"0; 1,2; 0; 1,2"},{"id":"b","label":"1,2; 0; 1,2; 0"},{"id":"c","label":"0,6; 0,6; 0,6; 0,6"},{"id":"d","label":"−1,2; 1,2; −1,2; 1,2"}]', 'a', 'Pro liché n je závorka 0, pro sudé n je 2; získáme 0, 1,2, 0, 1,2.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q14', 'posloupnosti-ss-diagnostika-v1', '14', '{"instruction":"Který přípustný index splňuje a_n=0?","math":"a_n=\\frac{n^2-2n}{5},\\quad n\\geq1","category":"Dosazování indexů a znaménka","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"n = 1"},{"id":"b","label":"n = 2"},{"id":"c","label":"n = 3"},{"id":"d","label":"n = 0"}]', 'b', 'n(n−2)=0. Index 0 není přípustný, proto n=2.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q15', 'posloupnosti-ss-diagnostika-v1', '15', '{"instruction":"Urči první tři členy.","math":"a_n=(-1)^n(n+1)","category":"Dosazování indexů a znaménka","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"2; −3; 4"},{"id":"b","label":"−2; 3; −4"},{"id":"c","label":"−1; 2; −3"},{"id":"d","label":"−2; −3; −4"}]', 'b', 'Pro n=1,2,3 dostáváme −2, 3, −4.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q16', 'posloupnosti-ss-diagnostika-v1', '16', '{"instruction":"Vyber předpis pro −1, −1/2, −1/3, −1/4, …","math":"","category":"Dosazování indexů a znaménka","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:-\\frac1n]]"},{"id":"b","label":"[[math:\\frac{(-1)^n}{n}]]"},{"id":"c","label":"[[math:-\\frac n{n+1}]]"},{"id":"d","label":"[[math:-n]]"}]', 'a', 'Jmenovatel se rovná n; znaménko je vždy záporné.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q17', 'posloupnosti-ss-diagnostika-v1', '17', '{"instruction":"Vyber vzorec pro členy 1/2, 2/3, 3/4, …","math":"","category":"Vzorce podle členů a rekurence","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:\\frac{n+1}{n}]]"},{"id":"b","label":"[[math:\\frac n{n+1}]]"},{"id":"c","label":"[[math:\\frac1{n+1}]]"},{"id":"d","label":"[[math:\\frac n{n+2}]]"}]', 'b', 'Čitatel n, jmenovatel n+1.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q18', 'posloupnosti-ss-diagnostika-v1', '18', '{"instruction":"Vyber vzorec pro členy 2/5, 3/6, 4/7, 5/8, …","math":"","category":"Vzorce podle členů a rekurence","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:\\frac n{n+3}]]"},{"id":"b","label":"[[math:\\frac{n+1}{n+4}]]"},{"id":"c","label":"[[math:\\frac{n+2}{n+5}]]"},{"id":"d","label":"[[math:\\frac{n+1}{n+3}]]"}]', 'b', 'Dosazení n=1 dá (n+1)/(n+4)=2/5, ostatní hodnoty také souhlasí.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q19', 'posloupnosti-ss-diagnostika-v1', '19', '{"instruction":"Urči předpis pro střídavé členy 1, −1/2, 1/3, −1/4, …","math":"","category":"Vzorce podle členů a rekurence","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:\\frac{(-1)^{n-1}}n]]"},{"id":"b","label":"[[math:\\frac{(-1)^n}n]]"},{"id":"c","label":"[[math:-\\frac1n]]"},{"id":"d","label":"[[math:\\frac{n}{(-1)^n}]]"}]', 'a', 'Střídání začíná kladnou jedničkou, proto je exponent n−1.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q20', 'posloupnosti-ss-diagnostika-v1', '20', '{"instruction":"Vypočti a5.","math":"a_1=0,\\ a_2=-1,\\ a_{n+2}=a_{n+1}+3a_n","category":"Vzorce podle členů a rekurence","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:−4]]"},{"id":"b","label":"[[math:−5]]"},{"id":"c","label":"[[math:−7]]"},{"id":"d","label":"[[math:−10]]"}]', 'c', 'a3=−1, a4=−4, a5=−4+3(−1)=−7.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q21', 'posloupnosti-ss-diagnostika-v1', '21', '{"instruction":"Vypočti a4.","math":"a_1=2,\\ a_2=-1,\\ a_{n+1}=-2a_n+a_{n-1}","category":"Vzorce podle členů a rekurence","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:−9]]"},{"id":"b","label":"[[math:9]]"},{"id":"c","label":"[[math:−5]]"},{"id":"d","label":"[[math:4]]"}]', 'a', 'a3=−2(−1)+2=4. a4=−2·4−1=−9.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q22', 'posloupnosti-ss-diagnostika-v1', '22', '{"instruction":"Vypočti a4.","math":"a_1=4,\\ a_{n+1}=\\frac12a_n+2n","category":"Vzorce podle členů a rekurence","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"7"},{"id":"b","label":"8"},{"id":"c","label":"9"},{"id":"d","label":"12,5"}]', 'c', 'a2=4, a3=6, a4=6/2+2·3=9.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q23', 'posloupnosti-ss-diagnostika-v1', '23', '{"instruction":"Posuď monotónnost.","math":"a_n=\\frac n{n+1}","category":"Vzorce podle členů a rekurence","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"Přísně rostoucí"},{"id":"b","label":"Přísně klesající"},{"id":"c","label":"Konstantní"},{"id":"d","label":"Není monotónní"}]', 'a', 'Rozdíl a_(n+1)−a_n=1/((n+1)(n+2))>0.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q24', 'posloupnosti-ss-diagnostika-v1', '24', '{"instruction":"Posuď monotónnost.","math":"a_n=\\frac{2n}{n+1}","category":"Vzorce podle členů a rekurence","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"Konstantní"},{"id":"b","label":"Přísně klesající"},{"id":"c","label":"Přísně rostoucí"},{"id":"d","label":"Není monotónní"}]', 'c', 'Rozdíl a_(n+1)−a_n=2/((n+1)(n+2))>0.', '2'),
  ('posloupnosti-ss-diagnostika-v1-q25', 'posloupnosti-ss-diagnostika-v1', '25', '{"instruction":"Vyjádři a_(n−2) a stanov podmínku na n.","math":"a_n=6-n","category":"Indexy, rekurence a monotónnost","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:8-n,\\ n\\geq3]]"},{"id":"b","label":"[[math:4-n,\\ n\\geq1]]"},{"id":"c","label":"[[math:8-n,\\ n\\geq1]]"},{"id":"d","label":"[[math:4-n,\\ n\\geq3]]"}]', 'a', 'Dosadíme n−2: 6−(n−2)=8−n. Platný index n−2≥1 vyžaduje n≥3.', '3'),
  ('posloupnosti-ss-diagnostika-v1-q26', 'posloupnosti-ss-diagnostika-v1', '26', '{"instruction":"Pro které indexy platí a_n≥−2?","math":"a_n=2-3n,\\quad n\\geq1","category":"Indexy, rekurence a monotónnost","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"Pro všechna n"},{"id":"b","label":"Pouze n = 1"},{"id":"c","label":"Pro n ≥ 2"},{"id":"d","label":"Pro n ≤ 2"}]', 'b', 'Z 2−3n≥−2 získáme n≤4/3. Jediný přípustný index je n=1.', '3'),
  ('posloupnosti-ss-diagnostika-v1-q27', 'posloupnosti-ss-diagnostika-v1', '27', '{"instruction":"Vyber předpis pro 1, −1, 3, −1, 5, −1, …","math":"","category":"Indexy, rekurence a monotónnost","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"Pro liché n je a_n=n, pro sudé a_n=−1"},{"id":"b","label":"Pro liché n je a_n=1, pro sudé a_n=−n"},{"id":"c","label":"a_n=(−1)^n"},{"id":"d","label":"a_n=2n−1"}]', 'a', 'Liché indexy dávají 1,3,5,..., tedy a_n=n. Sudé indexy jsou vždy −1.', '3'),
  ('posloupnosti-ss-diagnostika-v1-q28', 'posloupnosti-ss-diagnostika-v1', '28', '{"instruction":"Vyber předpis pro 1, 2, 2, 3, 3, 4, 4, …","math":"","category":"Indexy, rekurence a monotónnost","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:n+1]]"},{"id":"b","label":"[[math:\\lfloor n/2\\rfloor+1]]"},{"id":"c","label":"[[math:\\lceil n/2\\rceil]]"},{"id":"d","label":"[[math:2\\lfloor n/2\\rfloor]]"}]', 'b', 'Dolní celá část n/2 plus 1 dává hodnoty 1,2,2,3,3,4,4...', '3'),
  ('posloupnosti-ss-diagnostika-v1-q29', 'posloupnosti-ss-diagnostika-v1', '29', '{"instruction":"Vypočti a5.","math":"a_1=2,\\ a_2=1,\\ a_{n+2}=a_n^2-a_{n+1}^2","category":"Indexy, rekurence a monotónnost","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:−55]]"},{"id":"b","label":"[[math:−17]]"},{"id":"c","label":"[[math:55]]"},{"id":"d","label":"[[math:−8]]"}]', 'a', 'a3=4−1=3, a4=1−9=−8, a5=9−64=−55.', '3'),
  ('posloupnosti-ss-diagnostika-v1-q30', 'posloupnosti-ss-diagnostika-v1', '30', '{"instruction":"Rozhodni o monotónnosti pro n≥1.","math":"a_n=\\frac n{n^2+1}","category":"Indexy, rekurence a monotónnost","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"Přísně rostoucí"},{"id":"b","label":"Přísně klesající"},{"id":"c","label":"Konstantní"},{"id":"d","label":"Střídavá"}]', 'b', 'Rozdíl sousedních členů je (1−n−n²)/((n²+1)((n+1)²+1))<0 pro n≥1.', '3'),
  ('posloupnosti-ss-diagnostika-v1-q31', 'posloupnosti-ss-diagnostika-v1', '31', '{"instruction":"Urči rozdíl a_(n+1)−a_n.","math":"a_n=\\frac{2n}{n+1}","category":"Indexy, rekurence a monotónnost","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"[[math:\\frac2{(n+1)(n+2)}]]"},{"id":"b","label":"[[math:-\\frac2{(n+1)(n+2)}]]"},{"id":"c","label":"[[math:\\frac1{n+1}]]"},{"id":"d","label":"[[math:\\frac2{n+1}]]"}]', 'a', 'Po převedení na společný jmenovatel čitatel vyjde 2[(n+1)²−n(n+2)]=2.', '3'),
  ('posloupnosti-ss-diagnostika-v1-q32', 'posloupnosti-ss-diagnostika-v1', '32', '{"instruction":"Najdi index přirozeného členu, který má hodnotu 3.","math":"a_n=\\frac{n^2-2n}{5}","category":"Indexy, rekurence a monotónnost","hint":"Vyjdi z definice posloupnosti a pečlivě kontroluj index n."}', '[{"id":"a","label":"n = 3"},{"id":"b","label":"n = 4"},{"id":"c","label":"n = 5"},{"id":"d","label":"n = 6"}]', 'c', 'n²−2n=15, tedy (n−5)(n+3)=0. Přípustné je n=5.', '3');
